package com.jewellery360.domain;
import jakarta.persistence.*; import lombok.Getter; import lombok.Setter; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="purchase_return", uniqueConstraints=@UniqueConstraint(name="uk_purchase_return_company_no", columnNames="company_id,return_no"))
@Getter @Setter public class PurchaseReturn { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="company_id") private Company company; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="branch_id") private Branch branch; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="purchase_id") private PurchaseOrder purchase; @Column(nullable=false,length=80) private String returnNo; @Column(nullable=false) private LocalDate returnDate; @Column(nullable=false,precision=19,scale=3) private BigDecimal amount=BigDecimal.ZERO; @Column(length=1000) private String reason; @Column(nullable=false,length=30) private String status="COMPLETED"; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="created_by_id") private AppUser createdBy; @Column(nullable=false) private Instant createdAt=Instant.now(); }
